    let progress = step_index as f64 / total_items as f64;

    // Baseline: prioritize tight packing.
    let mut score = post_res * 0.92;

    // Lookahead: Dynamic dead-zone mitigation.
    // Increased sensitivity to the next item to prevent premature fragmentation.
    if next_item_size > 0 && post_res > 0.0 && post_res < next_item_size as f64 {
        let gap_waste = (next_item_size as f64 - post_res);
        score += gap_waste.powf(1.65) * (12.0 + (1.0 - progress) * 8.0);
    }

    // New Bin Gatekeeping:
    // Stricter enforcement of bin reuse via non-linear scaling of open_bins_count.
    if is_new_bin {
        if fitting_bins_count > 0 {
            let fragmentation_pressure = (open_bins_count as f64).powf(1.4) * 0.85 + (mean_residual * 1.5) + (progress * 95.0);
            score += 145.0 + fragmentation_pressure;
        } else {
            score -= 95.0; // Essential bin opening incentive.
        }
    }

    // Residual Homogenization:
    // Penalize outliers from the mean to ensure uniform bin depletion.
    if !is_new_bin {
        let deviation = (post_res - mean_residual).abs();
        score += deviation * 0.85;

        // Asymmetric penalty for "too-empty" bins relative to the mean.
        if post_res > mean_residual {
            score += (post_res - mean_residual) * 0.75;
        }
    }

    // Density Consolidation:
    // Focus on maximizing utilization of the specific bin capacity.
    let fill_ratio = 1.0 - (post_res / cap);
    score += (1.0 - fill_ratio).powf(2.8) * (45.0 + progress * 55.0);

    // Global Fragmentation Control:
    // Heavily penalize opening many bins early in the stream.
    score += (open_bins_count as f64).powf(1.45) * 2.15;

    // Tight Fit Reward:
    // Reward perfect fits and near-perfect fills exponentially.
    if post_res == 0.0 {
        score -= 55.0;
    } else if post_res < (cap * 0.15) {
        score -= 25.0 * (1.0 - (post_res / (cap * 0.15))).powf(0.8);
    }

    // Small Residual Trap:
    // Discourage bins that result in small, unusable residuals unless they hit the target.
    if !is_new_bin && post_res > 0.0 && post_res < (mean_residual * 0.4) {
        score += 22.0;
    }

    // Final sanity check: favor bins that keep the mean residual closer to 0.15 capacity.
    score += (mean_residual - (cap * 0.15)).abs() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
