            }
        }
    }

    // 3. Adaptive New Bin Control:
    // Discourage new bin creation unless necessary, but scale penalty by 
    // the current density to prevent excessive open bin counts.
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Penalty grows with the number of bins to encourage consolidation.
            score += 85.0 + (open_bins_count as f64 * 2.2) + (progress * 40.0);
        } else {
            score = 25.0; // Essential bin.
        }
    } else {
        // 4. Entropy Control:
        // Penalize deviations from the mean to keep bin residuals uniform.
        if (post_residual as f64) > mean_residual {
            score += (post_residual as f64 - mean_residual) * 1.8;
        }

        // 5. End-of-Stream Compaction:
        // Increase the cost of holding multiple bins open as we approach the end.
        score += (open_bins_count as f64) * progress * 8.0;
